-- ==============================================================================
-- MENSHOP DATABASE SCHEMA & MIGRATION (COMPLETE SETUP SCRIPT)
-- Generated by combining modular SQL scripts in correct dependency order
-- ==============================================================================


-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- MODULE: 01_types/01_extensions.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- ==============================================================================
-- 01. EXTENSIONS
-- MenShop / Menly Supabase
-- Kích hoạt extension pg_trgm phục vụ tìm kiếm gần đúng (fuzzy search) cho sản phẩm
-- ==============================================================================

create extension if not exists pg_trgm with schema extensions;


-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- MODULE: 01_types/02_enums.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- ==============================================================================
-- 02. CUSTOM ENUMS
-- MenShop / Menly Supabase
-- Khởi tạo các kiểu dữ liệu liệt kê (Enums) cho đơn hàng, thanh toán và kho
-- ==============================================================================

do $$ begin
  -- 1. Trạng thái đơn hàng (Bao gồm core và marketplace return/refund)
  if not exists (select 1 from pg_type where typname = 'order_status') then
    create type order_status as enum (
      'pending_payment',
      'pending_confirmation',
      'paid',
      'processing',
      'shipping',
      'completed',
      'cancelled',
      'return_requested',
      'returning',
      'returned',
      'refunded'
    );
  else
    -- Bổ sung các giá trị mới nếu type đã tồn tại trước đó
    alter type order_status add value if not exists 'pending_confirmation';
    alter type order_status add value if not exists 'return_requested';
    alter type order_status add value if not exists 'returning';
    alter type order_status add value if not exists 'returned';
    alter type order_status add value if not exists 'refunded';
  end if;

  -- 2. Trạng thái thanh toán VNPay
  if not exists (select 1 from pg_type where typname = 'payment_status') then
    create type payment_status as enum ('pending', 'success', 'failed');
  end if;

  -- 3. Lý do biến động tồn kho
  if not exists (select 1 from pg_type where typname = 'inventory_movement_reason') then
    create type inventory_movement_reason as enum (
      'order_created',
      'order_cancelled',
      'admin_restock',
      'admin_correction'
    );
  end if;
end $$;


-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- MODULE: 02_tables/01_profiles.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- ==============================================================================
-- BẢNG: PROFILES (HỒ SƠ NGƯỜI DÙNG & PHÂN QUYỀN)
-- Quản lý thông tin tài khoản người dùng, vai trò (admin, customer, user, seller),
-- trạng thái khóa tài khoản và khách vãng lai (guest).
-- ==============================================================================

create table if not exists public.profiles (
  id uuid primary key references auth.users on delete cascade,
  email text,
  full_name text,
  phone text,
  avatar_url text,
  role text not null default 'user' check (role in ('customer', 'admin', 'user', 'seller')),
  is_guest boolean not null default false,
  is_active boolean not null default true,
  is_locked boolean not null default false,
  created_at timestamptz not null default now()
);

-- Đảm bảo các cột và ràng buộc cập nhật nếu bảng đã tồn tại
alter table public.profiles add column if not exists email text;
alter table public.profiles add column if not exists avatar_url text;
alter table public.profiles add column if not exists is_locked boolean not null default false;

do $$ begin
  alter table public.profiles drop constraint if exists profiles_role_check;
  alter table public.profiles add constraint profiles_role_check check (role in ('customer', 'admin', 'user', 'seller', 'staff'));
exception
  when others then null;
end $$;


-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- MODULE: 02_tables/02_categories.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- ==============================================================================
-- BẢNG: CATEGORIES (DANH MỤC SẢN PHẨM THỜI TRANG NAM)
-- Lưu trữ các danh mục sản phẩm (Áo sơ mi, Polo, Quần Tây, Quần Jeans, Áo Khoác,...)
-- ==============================================================================

create table if not exists public.categories (
  id uuid primary key default gen_random_uuid(),
  name text not null,
  slug text not null unique,
  sort_order int not null default 0
);


-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- MODULE: 02_tables/03_shops.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- ==============================================================================
-- BẢNG: SHOPS (CỬA HÀNG / NGƯỜI BÁN TRÊN SÀN TMĐT)
-- Quản lý thông tin gian hàng của seller, logo, banner, điểm đánh giá uy tín
-- ==============================================================================

create table if not exists public.shops (
  id uuid primary key default gen_random_uuid(),
  owner_id uuid not null unique references auth.users on delete cascade,
  name text not null unique,
  slug text not null unique,
  description text,
  logo_url text,
  banner_url text,
  phone text not null,
  address text not null,
  status text not null default 'pending' check (status in ('pending', 'active', 'suspended', 'rejected')),
  rating_avg numeric(3,2) not null default 0.00 check (rating_avg between 0 and 5),
  rating_count int not null default 0,
  created_at timestamptz not null default now()
);


-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- MODULE: 02_tables/04_products.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- ==============================================================================
-- BẢNG: PRODUCTS (SẢN PHẨM THỜI TRANG NAM)
-- Lưu trữ sản phẩm chính, danh mục, giá niêm yết, chuỗi tìm kiếm không dấu,
-- liên kết gian hàng (shop_id), kiểm duyệt (approval_status) và rating trung bình.
-- ==============================================================================

create table if not exists public.products (
  id uuid primary key default gen_random_uuid(),
  category_id uuid not null references public.categories,
  shop_id uuid references public.shops on delete cascade,
  name text not null,
  slug text not null unique,
  description text,
  price int not null check (price >= 0),
  thumbnail_url text,
  search_text text not null default '',
  approval_status text not null default 'approved' check (approval_status in ('pending', 'approved', 'rejected')),
  rating_avg numeric(3,2) not null default 0.00,
  rating_count int not null default 0,
  is_active boolean not null default true,
  created_at timestamptz not null default now()
);

-- Bổ sung các cột nếu bảng đã tồn tại từ phiên bản trước
alter table public.products add column if not exists shop_id uuid references public.shops on delete cascade;
alter table public.products add column if not exists approval_status text not null default 'approved' check (approval_status in ('pending', 'approved', 'rejected'));
alter table public.products add column if not exists rating_avg numeric(3,2) not null default 0.00;
alter table public.products add column if not exists rating_count int not null default 0;


-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- MODULE: 02_tables/05_product_variants.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- ==============================================================================
-- BẢNG: PRODUCT_VARIANTS (BIẾN THỂ SẢN PHẨM: KÍCH CỠ, MÀU SẮC, TỒN KHO)
-- Quản lý tồn kho thực tế ở mức SKU (Size: M, L, XL; Màu sắc: Đen, Trắng, Xanh...)
-- ==============================================================================

create table if not exists public.product_variants (
  id uuid primary key default gen_random_uuid(),
  product_id uuid not null references public.products on delete cascade,
  size text not null,
  color text not null,
  sku text not null unique,
  stock int not null default 0 check (stock >= 0),
  unique (product_id, size, color)
);


-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- MODULE: 02_tables/06_product_images.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- ==============================================================================
-- BẢNG: PRODUCT_IMAGES (THƯ VIỆN HÌNH ẢNH SẢN PHẨM)
-- Lưu danh sách các góc chụp của sản phẩm và thứ tự hiển thị (sort_order)
-- ==============================================================================

create table if not exists public.product_images (
  id uuid primary key default gen_random_uuid(),
  product_id uuid not null references public.products on delete cascade,
  url text not null,
  sort_order int not null default 0
);


-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- MODULE: 02_tables/07_cart_items.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- ==============================================================================
-- BẢNG: CART_ITEMS (GIỎ HÀNG NGƯỜI DÙNG)
-- Lưu trữ các mặt hàng người dùng thêm vào giỏ trước khi tạo đơn hàng
-- ==============================================================================

create table if not exists public.cart_items (
  user_id uuid not null references auth.users on delete cascade,
  variant_id uuid not null references public.product_variants on delete cascade,
  quantity int not null check (quantity between 1 and 20),
  updated_at timestamptz not null default now(),
  primary key (user_id, variant_id)
);


-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- MODULE: 02_tables/08_orders.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- ==============================================================================
-- BẢNG: ORDERS (ĐƠN HÀNG)
-- Quản lý toàn bộ vòng đời đơn hàng: mã đơn, người mua, gian hàng (shop_id),
-- phương thức thanh toán (COD / VNPay), trạng thái, thông tin giao hàng, idempotency key
-- ==============================================================================

create table if not exists public.orders (
  id uuid primary key default gen_random_uuid(),
  code text not null unique,
  user_id uuid not null references auth.users,
  shop_id uuid references public.shops,
  parent_order_id uuid references public.orders(id) on delete cascade,
  status order_status not null default 'pending_payment',
  payment_method text not null check (payment_method in ('cod', 'vnpay')),
  subtotal int not null,
  shipping_fee int not null default 0,
  total int not null,
  ship_name text not null,
  ship_phone text not null,
  ship_address text not null,
  idempotency_key text,
  expires_at timestamptz,
  created_at timestamptz not null default now(),
  unique (user_id, idempotency_key)
);

-- Bổ sung cột shop_id và parent_order_id nếu bảng đã tồn tại
alter table public.orders add column if not exists shop_id uuid references public.shops;
alter table public.orders add column if not exists parent_order_id uuid references public.orders(id) on delete cascade;


-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- MODULE: 02_tables/09_order_items.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- ==============================================================================
-- BẢNG: ORDER_ITEMS (CHI TIẾT SẢN PHẨM TRONG ĐƠN HÀNG)
-- Lưu bản chụp bất biến (snapshot) tên sản phẩm, kích cỡ, màu sắc, đơn giá tại thời điểm đặt
-- ==============================================================================

create table if not exists public.order_items (
  id uuid primary key default gen_random_uuid(),
  order_id uuid not null references public.orders on delete cascade,
  variant_id uuid not null references public.product_variants,
  product_name text not null,
  size text not null,
  color text not null,
  unit_price int not null,
  quantity int not null check (quantity > 0)
);


-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- MODULE: 02_tables/10_payments.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- ==============================================================================
-- BẢNG: PAYMENTS (GIAO DỊCH CỔNG THANH TOÁN VNPAY)
-- Quản lý mã giao dịch đối soát txn_ref, số tiền, mã ngân hàng, phản hồi IPN
-- ==============================================================================

create table if not exists public.payments (
  id uuid primary key default gen_random_uuid(),
  order_id uuid not null references public.orders,
  provider text not null default 'vnpay',
  txn_ref text not null unique,
  amount int not null,
  status payment_status not null default 'pending',
  provider_txn_no text,
  bank_code text,
  response_code text,
  raw jsonb,
  created_at timestamptz not null default now(),
  paid_at timestamptz
);


-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- MODULE: 02_tables/11_inventory_movements.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- ==============================================================================
-- BẢNG: INVENTORY_MOVEMENTS (NHẬT KÝ BIẾN ĐỘNG TỒN KHO)
-- Ghi lại mọi lần tăng/giảm tồn kho: đặt hàng, hủy đơn hoàn kho, nhập hàng, điều chỉnh
-- ==============================================================================

create table if not exists public.inventory_movements (
  id uuid primary key default gen_random_uuid(),
  variant_id uuid not null references public.product_variants on delete cascade,
  change int not null,
  reason inventory_movement_reason not null,
  order_id uuid references public.orders,
  created_by uuid references auth.users,
  note text,
  created_at timestamptz not null default now()
);


-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- MODULE: 02_tables/12_order_status_history.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- ==============================================================================
-- BẢNG: ORDER_STATUS_HISTORY (LỊCH SỬ CHUYỂN TRẠNG THÁI ĐƠN HÀNG)
-- Lưu dấu vết thời gian thay đổi trạng thái đơn hàng và người thực hiện (admin/hệ thống)
-- ==============================================================================

create table if not exists public.order_status_history (
  id uuid primary key default gen_random_uuid(),
  order_id uuid not null references public.orders on delete cascade,
  from_status order_status,
  to_status order_status not null,
  changed_by uuid references auth.users,
  note text,
  created_at timestamptz not null default now()
);


-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- MODULE: 02_tables/13_admin_audit_log.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- ==============================================================================
-- BẢNG: ADMIN_AUDIT_LOG (NHẬT KÝ KIỂM TOÁN HÀNH VI QUẢN TRỊ VIÊN)
-- Ghi nhận các thao tác quan trọng: sửa giá, khóa tài khoản, duyệt shop, sửa đơn...
-- ==============================================================================

create table if not exists public.admin_audit_log (
  id uuid primary key default gen_random_uuid(),
  admin_id uuid not null references auth.users,
  action text not null,
  entity_type text not null,
  entity_id uuid,
  before jsonb,
  after jsonb,
  created_at timestamptz not null default now()
);


-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- MODULE: 02_tables/14_user_addresses.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- ==============================================================================
-- BẢNG: USER_ADDRESSES (SỔ ĐỊA CHỈ GIAO HÀNG CỦA NGƯỜI DÙNG)
-- Lưu danh sách địa chỉ nhận hàng của khách hàng (Tỉnh/Thành, Quận/Huyện, Phường/Xã)
-- ==============================================================================

create table if not exists public.user_addresses (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users on delete cascade,
  recipient_name text not null,
  phone text not null,
  province text not null,
  district text not null,
  ward text not null,
  detail_address text not null,
  is_default boolean not null default false,
  created_at timestamptz not null default now()
);


-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- MODULE: 02_tables/15_vouchers.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- ==============================================================================
-- BẢNG: VOUCHERS (MÃ GIẢM GIÁ TOÀN SÀN & SHOP)
-- Hỗ trợ voucher toàn sàn (shop_id = NULL) hoặc voucher riêng của từng Shop
-- ==============================================================================

create table if not exists public.vouchers (
  id uuid primary key default gen_random_uuid(),
  code text not null unique,
  shop_id uuid references public.shops on delete cascade,
  title text not null,
  discount_type text not null check (discount_type in ('percentage', 'fixed_amount')),
  discount_value int not null check (discount_value > 0),
  min_order_value int not null default 0,
  max_discount int,
  usage_limit int not null default 100,
  used_count int not null default 0,
  start_date timestamptz not null default now(),
  end_date timestamptz not null,
  is_active boolean not null default true,
  created_at timestamptz not null default now()
);


-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- MODULE: 02_tables/16_order_vouchers.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- ==============================================================================
-- BẢNG: ORDER_VOUCHERS (LIÊN KẾT VOUCHER ĐÃ ÁP DỤNG CHO ĐƠN HÀNG)
-- Lưu lại mã voucher và số tiền giảm giá thực tế cho đơn hàng
-- ==============================================================================

create table if not exists public.order_vouchers (
  id uuid primary key default gen_random_uuid(),
  order_id uuid not null references public.orders on delete cascade,
  voucher_id uuid not null references public.vouchers,
  discount_amount int not null check (discount_amount >= 0),
  created_at timestamptz not null default now()
);


-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- MODULE: 02_tables/17_product_reviews.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- ==============================================================================
-- BẢNG: PRODUCT_REVIEWS (ĐÁNH GIÁ & NHẬN XÉT SẢN PHẨM)
-- Cho phép khách hàng đã mua sản phẩm đánh giá số sao (1-5), gửi nhận xét, ảnh và shop phản hồi
-- ==============================================================================

create table if not exists public.product_reviews (
  id uuid primary key default gen_random_uuid(),
  product_id uuid not null references public.products on delete cascade,
  order_item_id uuid not null references public.order_items,
  user_id uuid not null references auth.users,
  rating int not null check (rating between 1 and 5),
  comment text,
  images jsonb default '[]'::jsonb,
  reply_comment text,
  reply_at timestamptz,
  created_at timestamptz not null default now(),
  unique (order_item_id)
);


-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- MODULE: 02_tables/18_order_returns.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- ==============================================================================
-- BẢNG: ORDER_RETURNS (YÊU CẦU TRẢ HÀNG & HOÀN TIỀN)
-- Quản lý quy trình đổi trả hàng, hình ảnh bằng chứng, xét duyệt của người bán & admin
-- ==============================================================================

create table if not exists public.order_returns (
  id uuid primary key default gen_random_uuid(),
  order_id uuid not null references public.orders on delete cascade,
  user_id uuid not null references auth.users,
  shop_id uuid not null references public.shops,
  reason text not null,
  proof_images jsonb default '[]'::jsonb,
  status text not null default 'requested' check (status in (
    'requested', 'shop_approved', 'shop_rejected', 'admin_dispute_review', 'refunded', 'rejected'
  )),
  refund_amount int not null,
  rejection_reason text,
  admin_resolution_note text,
  created_at timestamptz not null default now(),
  resolved_at timestamptz
);


-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- MODULE: 02_tables/19_wishlists.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- ==============================================================================
-- BẢNG: WISHLISTS (DANH SÁCH YÊU THÍCH SẢN PHẨM)
-- Lưu trữ sản phẩm người dùng đánh dấu quan tâm / yêu thích để mua sau
-- ==============================================================================

create table if not exists public.wishlists (
  user_id uuid not null references auth.users on delete cascade,
  product_id uuid not null references public.products on delete cascade,
  created_at timestamptz not null default now(),
  primary key (user_id, product_id)
);


-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- MODULE: 02_tables/20_shop_followers.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- ==============================================================================
-- BẢNG: SHOP_FOLLOWERS (THEO DÕI GIAN HÀNG)
-- Người dùng theo dõi shop để nhận thông báo hàng mới và voucher độc quyền
-- ==============================================================================

create table if not exists public.shop_followers (
  user_id uuid not null references auth.users on delete cascade,
  shop_id uuid not null references public.shops on delete cascade,
  created_at timestamptz not null default now(),
  primary key (user_id, shop_id)
);


-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- MODULE: 02_tables/21_chat_conversations.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- ==============================================================================
-- BẢNG: CHAT_CONVERSATIONS (HỘI THOẠI CHAT KHÁCH HÀNG & GIAN HÀNG)
-- Quản lý phòng chat trực tiếp giữa người mua và shop
-- ==============================================================================

create table if not exists public.chat_conversations (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users on delete cascade,
  shop_id uuid not null references public.shops on delete cascade,
  last_message text,
  last_message_at timestamptz default now(),
  unread_user_count int not null default 0,
  unread_shop_count int not null default 0,
  created_at timestamptz not null default now(),
  unique (user_id, shop_id)
);


-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- MODULE: 02_tables/22_chat_messages.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- ==============================================================================
-- BẢNG: CHAT_MESSAGES (TIN NHẮN CHAT REALTIME)
-- Hỗ trợ tin nhắn văn bản và hình ảnh đính kèm, trạng thái đã xem (is_read)
-- ==============================================================================

create table if not exists public.chat_messages (
  id uuid primary key default gen_random_uuid(),
  conversation_id uuid not null references public.chat_conversations on delete cascade,
  sender_id uuid not null references auth.users,
  message_type text not null default 'text' check (message_type in ('text', 'image')),
  content text not null,
  is_read boolean not null default false,
  created_at timestamptz not null default now()
);


-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- MODULE: 02_tables/23_notifications.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- ==============================================================================
-- BẢNG: NOTIFICATIONS (THÔNG BÁO ĐẨY / HỆ THỐNG)
-- Thông báo tiến trình đơn hàng (order), khuyến mãi (promo) và hệ thống (system)
-- ==============================================================================

create table if not exists public.notifications (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users on delete cascade,
  title text not null,
  body text not null,
  type text not null check (type in ('order', 'promo', 'system')),
  data jsonb default '{}'::jsonb,
  is_read boolean not null default false,
  created_at timestamptz not null default now()
);


-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- MODULE: 02_tables/24_banners.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- ==============================================================================
-- BẢNG: BANNERS (BANNER QUẢNG CÁO & SLIDER TRANG CHỦ)
-- Quản lý hình ảnh banner hiển thị trên ứng dụng mobile và trang web
-- ==============================================================================

create table if not exists public.banners (
  id uuid primary key default gen_random_uuid(),
  title text not null,
  image_url text not null,
  link_url text,
  sort_order int not null default 0,
  is_active boolean not null default true,
  start_date timestamptz not null default now(),
  end_date timestamptz not null
);


-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- MODULE: 02_tables/25_flash_sales.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- ==============================================================================
-- BẢNG: FLASH_SALES & FLASH_SALE_ITEMS (CHƯƠNG TRÌNH KHUYẾN MÃI CHỚP NHOÁNG)
-- Quản lý khung giờ Flash Sale, giới hạn số lượng và giá ưu đãi đặc biệt
-- ==============================================================================

create table if not exists public.flash_sales (
  id uuid primary key default gen_random_uuid(),
  title text not null,
  start_time timestamptz not null,
  end_time timestamptz not null,
  is_active boolean not null default false
);

create table if not exists public.flash_sale_items (
  id uuid primary key default gen_random_uuid(),
  flash_sale_id uuid not null references public.flash_sales on delete cascade,
  variant_id uuid not null references public.product_variants on delete cascade,
  sale_price int not null check (sale_price > 0),
  quantity_limit int not null check (quantity_limit > 0),
  sold_count int not null default 0,
  unique (flash_sale_id, variant_id)
);


-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- MODULE: 03_indexes/01_product_indexes.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- ==============================================================================
-- INDEXES: SẢN PHẨM & BIẾN THỂ (TỐI ƯU TRUY VẤN VÀ TÌM KIẾM)
-- Tối ưu hóa phân trang theo ngày, theo giá, theo danh mục, shop và tìm kiếm tiếng Việt
-- ==============================================================================

-- 1. Tối ưu sắp xếp sản phẩm mới nhất
create index if not exists products_newest_idx on public.products (created_at desc, id desc) where is_active;

-- 2. Tối ưu lọc và sắp xếp theo giá
create index if not exists products_price_idx on public.products (price, id) where is_active;

-- 3. Tối ưu lọc theo danh mục
create index if not exists products_category_idx on public.products (category_id, created_at desc, id desc) where is_active;

-- 4. Tìm kiếm Full-text/Fuzzy search bằng pg_trgm
create index if not exists products_search_trgm on public.products using gin (search_text extensions.gin_trgm_ops);

-- 5. Liên kết khóa ngoại giữa biến thể và sản phẩm
create index if not exists variants_product_idx on public.product_variants (product_id);

-- 6. Tối ưu lấy sản phẩm theo gian hàng (shop)
create index if not exists products_shop_idx on public.products (shop_id, created_at desc);


-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- MODULE: 03_indexes/02_order_indexes.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- ==============================================================================
-- INDEXES: ĐƠN HÀNG & LỊCH SỬ ĐƠN HÀNG (TỐI ƯU ADMIN & CUSTOMER QUERY)
-- ==============================================================================

-- 1. Lọc đơn hàng của khách hàng theo thời gian
create index if not exists orders_user_idx on public.orders (user_id, created_at desc, id desc);

-- 2. Tối ưu thống kê và phân trang dashboard quản trị viên
create index if not exists orders_created_at_idx on public.orders (created_at desc, id desc);

-- 3. Lọc nhanh đơn hàng theo trạng thái (status)
create index if not exists orders_status_created_idx on public.orders (status, created_at desc);

-- 4. Tối ưu lấy chi tiết sản phẩm theo order_id
create index if not exists order_items_order_idx on public.order_items (order_id);

-- 5. Lọc đơn hàng theo gian hàng (shop)
create index if not exists orders_shop_idx on public.orders (shop_id, created_at desc);

-- 6. Lịch sử thay đổi trạng thái đơn
create index if not exists order_history_idx on public.order_status_history (order_id);


-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- MODULE: 03_indexes/03_marketplace_indexes.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- ==============================================================================
-- INDEXES: HỆ THỐNG MARKETPLACE (THANH TOÁN, TỒN KHO, ĐÁNH GIÁ, CHAT, THÔNG BÁO)
-- ==============================================================================

-- 1. Thanh toán theo đơn hàng
create index if not exists payments_order_idx on public.payments (order_id);

-- 2. Biến động tồn kho theo biến thể
create index if not exists inventory_var_idx on public.inventory_movements (variant_id);

-- 3. Đánh giá theo sản phẩm
create index if not exists reviews_product_idx on public.product_reviews (product_id, created_at desc);

-- 4. Trả hàng theo đơn hàng và shop
create index if not exists returns_order_idx on public.order_returns (order_id);
create index if not exists returns_shop_idx on public.order_returns (shop_id, status);

-- 5. Hội thoại và tin nhắn chat realtime
create index if not exists chat_conv_user_shop on public.chat_conversations (user_id, shop_id);
create index if not exists chat_msg_conv_idx on public.chat_messages (conversation_id, created_at);

-- 6. Thông báo người dùng chưa đọc
create index if not exists notif_user_idx on public.notifications (user_id, is_read, created_at desc);

-- 7. Tìm kiếm mã voucher đang hoạt động
create index if not exists vouchers_code_idx on public.vouchers (code) where is_active;

-- 8. Banner trang chủ theo thứ tự ưu tiên
create index if not exists banners_active_idx on public.banners (is_active, sort_order);


-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- MODULE: 04_triggers/01_handle_new_user.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- ==============================================================================
-- TRIGGER & FUNCTION: HANDLE_NEW_USER
-- Tự động khởi tạo hồ sơ người dùng trong public.profiles khi có user mới tạo ở auth.users
-- ==============================================================================

create or replace function public.handle_new_user() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  insert into public.profiles (id, email, full_name, role, is_guest, is_active, is_locked)
  values (
    new.id,
    new.email,
    coalesce(new.raw_user_meta_data->>'full_name', new.raw_user_meta_data->>'name', split_part(new.email, '@', 1)),
    coalesce(new.raw_user_meta_data->>'role', 'user'),
    coalesce(new.is_anonymous, false),
    true,
    false
  )
  on conflict (id) do update set
    email = excluded.email,
    full_name = coalesce(excluded.full_name, profiles.full_name),
    role = coalesce(excluded.role, profiles.role);
  return new;
end $$;

drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created
after insert on auth.users for each row execute function public.handle_new_user();


-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- MODULE: 04_triggers/02_handle_user_anonymity_change.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- ==============================================================================
-- TRIGGER & FUNCTION: HANDLE_USER_ANONYMITY_CHANGE
-- Tự động cập nhật cờ is_guest trong profiles khi tài khoản ẩn danh chuyển thành chính thức
-- ==============================================================================

create or replace function public.handle_user_anonymity_change() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if new.is_anonymous is distinct from old.is_anonymous then
    update public.profiles set is_guest = coalesce(new.is_anonymous, false) where id = new.id;
  end if;
  return new;
end $$;

drop trigger if exists on_auth_user_anonymity_change on auth.users;
create trigger on_auth_user_anonymity_change
after update of is_anonymous on auth.users
for each row execute function public.handle_user_anonymity_change();


-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- MODULE: 04_triggers/03_update_product_and_shop_rating.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- ==============================================================================
-- TRIGGER & FUNCTION: UPDATE_PRODUCT_AND_SHOP_RATING
-- Tự động tính điểm uy tín trung bình (rating_avg, rating_count) cho Sản phẩm & Gian hàng
-- khi người dùng gửi đánh giá sản phẩm mới
-- ==============================================================================

create or replace function public.update_product_and_shop_rating()
returns trigger language plpgsql security definer as $$
declare
  v_shop_id uuid;
begin
  -- 1. Cập nhật rating sản phẩm
  update public.products
  set rating_avg = round((select coalesce(avg(rating), 0) from public.product_reviews where product_id = new.product_id), 2),
      rating_count = (select count(*) from public.product_reviews where product_id = new.product_id)
  where id = new.product_id
  returning shop_id into v_shop_id;

  -- 2. Cập nhật rating của shop (nếu sản phẩm thuộc shop)
  if v_shop_id is not null then
    update public.shops
    set rating_avg = round((
      select coalesce(avg(r.rating), 0)
      from public.product_reviews r
      join public.products p on p.id = r.product_id
      where p.shop_id = v_shop_id
    ), 2),
    rating_count = (
      select count(*)
      from public.product_reviews r
      join public.products p on p.id = r.product_id
      where p.shop_id = v_shop_id
    )
    where id = v_shop_id;
  end if;

  return new;
end $$;

drop trigger if exists on_product_review_added on public.product_reviews;
create trigger on_product_review_added
after insert on public.product_reviews
for each row execute function public.update_product_and_shop_rating();


-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- MODULE: 05_functions/01_is_admin.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- ==============================================================================
-- FUNCTION: IS_ADMIN
-- Kiểm tra token người dùng có quyền Admin thông qua auth.jwt() app_metadata
-- Sử dụng trong các chính sách Row Level Security (RLS)
-- ==============================================================================

create or replace function public.is_admin() returns boolean
language sql stable as $$
  select coalesce((auth.jwt() -> 'app_metadata' ->> 'role') = 'admin', false);
$$;

-- FUNCTION: IS_STAFF_OR_ADMIN
-- Kiểm tra token người dùng có quyền Nhân viên hoặc Admin để thực hiện các thao tác vận hành
create or replace function public.is_staff_or_admin() returns boolean
language sql stable as $$
  select coalesce(
    (auth.jwt() -> 'app_metadata' ->> 'role') in ('admin', 'staff'),
    false
  );
$$;


-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- MODULE: 05_functions/02_set_user_role.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- ==============================================================================
-- FUNCTION: SET_USER_ROLE
-- Phân quyền tài khoản (customer, admin, user) đồng bộ giữa auth.users và public.profiles
-- Bảo mật: Chỉ được phép gọi từ service_role (Backend API)
-- ==============================================================================

create or replace function public.set_user_role(p_user_id uuid, p_role text)
returns void
language plpgsql security definer set search_path = public as $$
begin
  if p_role not in ('customer', 'admin', 'user', 'seller') then
    raise exception 'INVALID_ROLE:%', p_role;
  end if;

  update auth.users
     set raw_app_meta_data = coalesce(raw_app_meta_data, '{}'::jsonb) || jsonb_build_object('role', p_role)
   where id = p_user_id;

  if not found then
    raise exception 'USER_NOT_FOUND:%', p_user_id;
  end if;

  update public.profiles set role = p_role where id = p_user_id;
end $$;

-- Phân quyền
revoke all on function public.set_user_role(uuid, text) from public, anon, authenticated;
grant execute on function public.set_user_role(uuid, text) to service_role;


-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- MODULE: 05_functions/03_create_order.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- ==============================================================================
-- RPC FUNCTION: CREATE_ORDER
-- Đặt hàng toàn vẹn ACID:
-- 1. Chống duplicate đơn với Idempotency Key
-- 2. Khóa dòng biến thể (SELECT FOR UPDATE) để chống bán vượt tồn kho (race condition)
-- 3. Trừ tồn kho và ghi nhật ký inventory_movements
-- 4. Tạo bản ghi đơn hàng và chi tiết sản phẩm order_items
-- 5. Dọn dẹp giỏ hàng cart_items
-- ==============================================================================

create or replace function public.create_order(
  p_user_id uuid,
  p_items jsonb,
  p_ship jsonb,
  p_method text,
  p_shipping_fee int,
  p_idem_key text
) returns uuid
language plpgsql security definer set search_path = public as $$
declare
  v_id uuid;
  v_sub int := 0;
  r record;
  v record;
begin
  -- 1. Kiểm tra đơn hàng trùng lặp theo idempotency key
  select id into v_id from orders
   where user_id = p_user_id and idempotency_key = p_idem_key;
  if found then return v_id; end if;

  -- 2. Tạo đơn hàng mới
  insert into orders (
    code, user_id, status, payment_method, subtotal, total, shipping_fee,
    ship_name, ship_phone, ship_address, idempotency_key, expires_at
  )
  values (
    'MS' || to_char(now() at time zone 'Asia/Ho_Chi_Minh', 'YYMMDD')
         || upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 6)),
    p_user_id,
    (case when p_method = 'vnpay' then 'pending_payment' else 'processing' end)::order_status,
    p_method, 0, 0, p_shipping_fee,
    p_ship->>'name', p_ship->>'phone', p_ship->>'address',
    p_idem_key,
    case when p_method = 'vnpay' then now() + interval '15 minutes' end
  ) returning id into v_id;

  -- 3. Xử lý từng sản phẩm trong đơn, khóa biến thể và trừ tồn kho
  for r in
    select (e->>'variant_id')::uuid as variant_id, (e->>'quantity')::int as qty
      from jsonb_array_elements(p_items) e
     order by variant_id
  loop
    select pv.id, pv.size, pv.color, pv.stock, p.name, p.price into v
      from product_variants pv join products p on p.id = pv.product_id
     where pv.id = r.variant_id and p.is_active
       for update of pv;

    if not found or v.stock < r.qty then
      raise exception 'OUT_OF_STOCK:%', r.variant_id;
    end if;

    -- Trừ tồn kho
    update product_variants set stock = stock - r.qty where id = r.variant_id;

    -- Ghi nhật ký biến động kho
    insert into inventory_movements (variant_id, change, reason, order_id, created_by, note)
    values (r.variant_id, -r.qty, 'order_created', v_id, p_user_id, 'Khách đặt hàng');

    -- Thêm chi tiết đơn hàng
    insert into order_items (order_id, variant_id, product_name, size, color, unit_price, quantity)
    values (v_id, v.id, v.name, v.size, v.color, v.price, r.qty);

    v_sub := v_sub + v.price * r.qty;
  end loop;

  -- 4. Cập nhật lại tổng tiền đơn hàng
  update orders set subtotal = v_sub, total = v_sub + p_shipping_fee where id = v_id;

  -- 5. Xóa các món hàng tương ứng khỏi giỏ hàng
  delete from cart_items
   where user_id = p_user_id
     and variant_id in (select (e->>'variant_id')::uuid from jsonb_array_elements(p_items) e);

  return v_id;
end $$;

-- Phân quyền
revoke all on function public.create_order(uuid, jsonb, jsonb, text, int, text) from public, anon, authenticated;
grant execute on function public.create_order(uuid, jsonb, jsonb, text, int, text) to service_role;


-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- MODULE: 05_functions/04_settle_payment.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- ==============================================================================
-- RPC FUNCTION: SETTLE_PAYMENT
-- Xử lý xác nhận thanh toán VNPay IPN webhook:
-- Cập nhật giao dịch payments, và chuyển trạng thái đơn hàng orders sang 'paid'
-- ==============================================================================

create or replace function public.settle_payment(
  p_txn_ref text,
  p_success boolean,
  p_txn_no text,
  p_bank text,
  p_code text,
  p_raw jsonb
) returns text
language plpgsql security definer set search_path = public as $$
declare
  v_order uuid;
begin
  update payments
     set status = (case when p_success then 'success' else 'failed' end)::payment_status,
         provider_txn_no = p_txn_no,
         bank_code = p_bank,
         response_code = p_code,
         raw = p_raw,
         paid_at = case when p_success then now() end
   where txn_ref = p_txn_ref and status = 'pending'
   returning order_id into v_order;

  if not found then
    return 'already';
  end if;

  if p_success then
    update orders set status = 'paid' where id = v_order and status = 'pending_payment';
  end if;

  return 'ok';
end $$;

-- Phân quyền
revoke all on function public.settle_payment(text, boolean, text, text, text, jsonb) from public, anon, authenticated;
grant execute on function public.settle_payment(text, boolean, text, text, text, jsonb) to service_role;


-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- MODULE: 05_functions/05_expire_pending_orders.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- ==============================================================================
-- RPC FUNCTION: EXPIRE_PENDING_ORDERS
-- Tự động hủy các đơn hàng thanh toán VNPay hết hạn (sau 15 phút) chưa hoàn tất:
-- Chuyển trạng thái đơn sang 'cancelled', tự động hoàn lại tồn kho biến thể
-- và ghi nhận lý do 'order_cancelled' vào inventory_movements.
-- ==============================================================================

create or replace function public.expire_pending_orders() returns int
language plpgsql security definer set search_path = public as $$
declare
  n int;
begin
  with c as (
    update orders set status = 'cancelled'
     where status = 'pending_payment' and expires_at < now()
    returning id
  ), s as (
    select oi.variant_id, sum(oi.quantity)::int as q, c.id as order_id
      from order_items oi join c on c.id = oi.order_id
     group by oi.variant_id, c.id
  ), u as (
    update product_variants pv set stock = pv.stock + s.q
      from s where pv.id = s.variant_id
    returning 1
  ), m as (
    insert into inventory_movements (variant_id, change, reason, order_id, note)
    select s.variant_id, s.q, 'order_cancelled', s.order_id, 'Đơn VNPay hết hạn tự động hoàn kho'
    from s
    returning 1
  )
  select count(*) into n from c;
  return n;
end $$;

-- Phân quyền
revoke all on function public.expire_pending_orders() from public, anon, authenticated;
grant execute on function public.expire_pending_orders() to service_role;


-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- MODULE: 05_functions/06_adjust_stock.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- ==============================================================================
-- RPC FUNCTION: ADJUST_STOCK
-- Quản trị viên điều chỉnh tồn kho thủ công (nhập hàng mới hoặc kiểm kê sai lệch)
-- ==============================================================================

create or replace function public.adjust_stock(
  p_variant_id uuid,
  p_delta int,
  p_reason inventory_movement_reason,
  p_note text default null,
  p_admin_id uuid default null
) returns int
language plpgsql security definer set search_path = public as $$
declare
  v_new int;
begin
  if p_reason not in ('admin_restock', 'admin_correction') then
    raise exception 'INVALID_REASON:%', p_reason;
  end if;

  update product_variants
     set stock = stock + p_delta
   where id = p_variant_id and stock + p_delta >= 0
   returning stock into v_new;

  if not found then
    raise exception 'INVALID_ADJUSTMENT:variant=% delta=%', p_variant_id, p_delta;
  end if;

  insert into inventory_movements (variant_id, change, reason, created_by, note)
  values (p_variant_id, p_delta, p_reason, p_admin_id, p_note);

  return v_new;
end $$;

-- Phân quyền
revoke all on function public.adjust_stock(uuid, int, inventory_movement_reason, text, uuid) from public, anon, authenticated;
grant execute on function public.adjust_stock(uuid, int, inventory_movement_reason, text, uuid) to service_role;


-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- MODULE: 05_functions/07_admin_update_order_status.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- ==============================================================================
-- RPC FUNCTION: ADMIN_UPDATE_ORDER_STATUS
-- Admin cập nhật tiến trình đơn hàng (processing, shipping, completed, cancelled)
-- Kiểm tra state machine hợp lệ và tự động hoàn kho nếu đơn bị hủy
-- ==============================================================================

create or replace function public.admin_update_order_status(
  p_order_id uuid,
  p_new_status order_status,
  p_note text default null,
  p_admin_id uuid default null
) returns void
language plpgsql security definer set search_path = public as $$
declare
  v_old order_status;
begin
  if p_admin_id is not null and not exists (
    select 1 from profiles where id = p_admin_id and role = 'admin'
  ) then
    raise exception 'FORBIDDEN';
  end if;

  select status into v_old from orders where id = p_order_id for update;
  if not found then raise exception 'ORDER_NOT_FOUND:%', p_order_id; end if;

  -- Kiểm tra chuyển đổi trạng thái hợp lệ
  if not (
    (v_old = 'pending_payment'      and p_new_status = 'cancelled') or
    (v_old = 'pending_confirmation' and p_new_status in ('processing', 'cancelled')) or
    (v_old = 'paid'                 and p_new_status in ('processing', 'cancelled')) or
    (v_old = 'processing'           and p_new_status in ('shipping', 'cancelled')) or
    (v_old = 'shipping'             and p_new_status in ('completed', 'cancelled')) or
    (v_old = 'return_requested'     and p_new_status in ('returning', 'cancelled')) or
    (v_old = 'returning'            and p_new_status in ('returned', 'completed')) or
    (v_old = 'returned'             and p_new_status in ('refunded'))
  ) then
    raise exception 'INVALID_TRANSITION:% -> %', v_old, p_new_status;
  end if;

  -- Nếu hủy đơn, tự động hoàn trả tồn kho cho tất cả sản phẩm trong đơn
  if p_new_status = 'cancelled' then
    insert into inventory_movements (variant_id, change, reason, order_id, created_by, note)
    select oi.variant_id, oi.quantity, 'order_cancelled', p_order_id, p_admin_id, coalesce(p_note, 'Hủy bởi admin')
      from order_items oi where oi.order_id = p_order_id;

    update product_variants pv set stock = pv.stock + oi.quantity
      from order_items oi where oi.variant_id = pv.id and oi.order_id = p_order_id;
  end if;

  update orders set status = p_new_status where id = p_order_id;

  insert into order_status_history (order_id, from_status, to_status, changed_by, note)
  values (p_order_id, v_old, p_new_status, p_admin_id, p_note);
end $$;

-- Phân quyền
revoke all on function public.admin_update_order_status(uuid, order_status, text, uuid) from public, anon, authenticated;
grant execute on function public.admin_update_order_status(uuid, order_status, text, uuid) to service_role;


-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- MODULE: 05_functions/08_track_order_by_code_phone.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- ==============================================================================
-- RPC FUNCTION: TRACK_ORDER_BY_CODE_PHONE
-- Tra cứu đơn hàng công khai: Khách hàng không cần đăng nhập vẫn có thể
-- tra cứu trạng thái đơn hàng thông qua Mã Đơn Hàng + Số Điện Thoại
-- ==============================================================================

create or replace function public.track_order_by_code_phone(p_code text, p_phone text)
returns table (
  id uuid,
  code text,
  status order_status,
  total int,
  payment_method text,
  created_at timestamptz,
  items jsonb
)
language sql security definer set search_path = public as $$
  select
    o.id,
    o.code,
    o.status,
    o.total,
    o.payment_method,
    o.created_at,
    (
      select jsonb_agg(jsonb_build_object(
        'productName', oi.product_name,
        'size', oi.size,
        'color', oi.color,
        'quantity', oi.quantity,
        'unitPrice', oi.unit_price
      ))
      from order_items oi
      where oi.order_id = o.id
    ) as items
  from orders o
  where o.code = p_code and o.ship_phone = p_phone;
$$;

-- Phân quyền cho anon và service_role
revoke all on function public.track_order_by_code_phone(text, text) from public, authenticated;
grant execute on function public.track_order_by_code_phone(text, text) to anon, authenticated, service_role;


-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- MODULE: 05_functions/09_cancel_order_by_buyer.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- ==============================================================================
-- RPC FUNCTION: CANCEL_ORDER_BY_BUYER
-- Khách hàng tự hủy đơn hàng khi đơn chưa được shop đóng gói / xác nhận:
-- Tự động hoàn trả số lượng tồn kho cho các biến thể sản phẩm trong đơn.
-- ==============================================================================

create or replace function public.cancel_order_by_buyer(p_order_id uuid, p_user_id uuid)
returns void language plpgsql security definer set search_path = public as $$
declare
  v_order record;
  v_item record;
begin
  select * into v_order from public.orders where id = p_order_id and user_id = p_user_id for update;
  if not found then
    raise exception 'Không tìm thấy đơn hàng hoặc bạn không có quyền hủy';
  end if;

  if v_order.status not in ('pending_payment', 'pending_confirmation') then
    raise exception 'Đơn hàng đã được người bán xử lý đóng gói, không thể tự hủy';
  end if;

  -- Hoàn lại số lượng tồn kho cho các biến thể
  for v_item in select variant_id, quantity from public.order_items where order_id = p_order_id loop
    update public.product_variants
       set stock = stock + v_item.quantity
     where id = v_item.variant_id;

    insert into public.inventory_movements (variant_id, change, reason, order_id, created_by, note)
    values (v_item.variant_id, v_item.quantity, 'order_cancelled', p_order_id, p_user_id, 'Khách hàng tự hủy đơn');
  end loop;

  update public.orders set status = 'cancelled' where id = p_order_id;

  insert into public.order_status_history (order_id, from_status, to_status, changed_by, note)
  values (p_order_id, v_order.status, 'cancelled', p_user_id, 'Khách hàng tự hủy đơn');
end $$;

-- Phân quyền
revoke all on function public.cancel_order_by_buyer(uuid, uuid) from public, anon;
grant execute on function public.cancel_order_by_buyer(uuid, uuid) to authenticated, service_role;


-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- MODULE: 06_policies/01_enable_rls.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- ==============================================================================
-- 01. BẬT ROW LEVEL SECURITY (RLS) CHO CÁC BẢNG TRONG HỆ THỐNG
-- Đảm bảo an toàn dữ liệu, ngăn chặn truy cập trái phép qua Supabase Client
-- ==============================================================================

alter table public.profiles          enable row level security;
alter table public.categories        enable row level security;
alter table public.products          enable row level security;
alter table public.product_variants  enable row level security;
alter table public.product_images    enable row level security;
alter table public.cart_items        enable row level security;
alter table public.orders            enable row level security;
alter table public.order_items       enable row level security;
alter table public.payments          enable row level security;
alter table public.inventory_movements enable row level security;
alter table public.order_status_history enable row level security;
alter table public.admin_audit_log   enable row level security;

-- Marketplace tables
alter table public.shops             enable row level security;
alter table public.user_addresses    enable row level security;
alter table public.vouchers          enable row level security;
alter table public.order_vouchers    enable row level security;
alter table public.product_reviews   enable row level security;
alter table public.order_returns     enable row level security;
alter table public.wishlists         enable row level security;
alter table public.shop_followers    enable row level security;
alter table public.chat_conversations enable row level security;
alter table public.chat_messages     enable row level security;
alter table public.notifications     enable row level security;
alter table public.banners           enable row level security;
alter table public.flash_sales       enable row level security;
alter table public.flash_sale_items  enable row level security;


-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- MODULE: 06_policies/02_catalog_policies.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- ==============================================================================
-- 02. RLS POLICIES: CATALOG ĐỌC DỮ LIỆU CÔNG KHAI (ANON & AUTHENTICATED)
-- Cho phép khách vãng lai và người dùng đã đăng nhập xem danh mục, sản phẩm, hình ảnh, banner
-- ==============================================================================

-- 1. Đọc danh mục sản phẩm
drop policy if exists "catalog read" on public.categories;
create policy "catalog read" on public.categories
  for select to anon, authenticated using (true);

-- 2. Đọc sản phẩm đang hoạt động
drop policy if exists "catalog read" on public.products;
create policy "catalog read" on public.products
  for select to anon, authenticated using (is_active);

-- 3. Đọc biến thể sản phẩm
drop policy if exists "catalog read" on public.product_variants;
create policy "catalog read" on public.product_variants
  for select to anon, authenticated using (true);

-- 4. Đọc hình ảnh sản phẩm
drop policy if exists "catalog read" on public.product_images;
create policy "catalog read" on public.product_images
  for select to anon, authenticated using (true);

-- 5. Đọc banner quảng cáo đang hoạt động
drop policy if exists "banners public read" on public.banners;
create policy "banners public read" on public.banners
  for select to anon, authenticated using (is_active);

-- 6. Đọc thông tin cửa hàng đang hoạt động
drop policy if exists "shops public read" on public.shops;
create policy "shops public read" on public.shops
  for select to anon, authenticated using (status = 'active');

-- 7. Đọc đánh giá sản phẩm
drop policy if exists "reviews public read" on public.product_reviews;
create policy "reviews public read" on public.product_reviews
  for select to anon, authenticated using (true);


-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- MODULE: 06_policies/03_user_profile_policies.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- ==============================================================================
-- 03. RLS POLICIES: DỮ LIỆU CÁ NHÂN CỦA NGƯỜI DÙNG (USER OWNS DATA)
-- Khách hàng chỉ được phép xem & chỉnh sửa thông tin thuộc về chính mình
-- ==============================================================================

-- 1. Xem và sửa hồ sơ cá nhân
drop policy if exists "own profile read" on public.profiles;
create policy "own profile read" on public.profiles
  for select to authenticated using (id = (select auth.uid()));

drop policy if exists "own profile update" on public.profiles;
create policy "own profile update" on public.profiles
  for update to authenticated using (id = (select auth.uid()));

-- 2. Quản lý giỏ hàng của chính mình
drop policy if exists "own cart read" on public.cart_items;
create policy "own cart read" on public.cart_items
  for select to authenticated using (user_id = (select auth.uid()));

drop policy if exists "own cart modify" on public.cart_items;
create policy "own cart modify" on public.cart_items
  for all to authenticated
  using (user_id = (select auth.uid()))
  with check (user_id = (select auth.uid()));

-- 3. Xem danh sách đơn hàng của chính mình
drop policy if exists "own orders read" on public.orders;
create policy "own orders read" on public.orders
  for select to authenticated using (user_id = (select auth.uid()));

-- 4. Quản lý địa chỉ giao hàng của chính mình
drop policy if exists "own addresses all" on public.user_addresses;
create policy "own addresses all" on public.user_addresses
  for all to authenticated
  using (user_id = (select auth.uid()))
  with check (user_id = (select auth.uid()));

-- 5. Quản lý sản phẩm yêu thích (wishlist)
drop policy if exists "own wishlists all" on public.wishlists;
create policy "own wishlists all" on public.wishlists
  for all to authenticated
  using (user_id = (select auth.uid()))
  with check (user_id = (select auth.uid()));

-- 6. Quản lý thông báo cá nhân
drop policy if exists "own notifications read" on public.notifications;
create policy "own notifications read" on public.notifications
  for select to authenticated using (user_id = (select auth.uid()));


-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- MODULE: 06_policies/04_admin_policies.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- ==============================================================================
-- 04. RLS POLICIES: QUYỀN QUẢN TRỊ VIÊN & NHÂN VIÊN VẬN HÀNH (STAFF & ADMIN)
-- - Quản trị viên (admin): Toàn quyền trên mọi bảng kể cả quản lý tài khoản người dùng
-- - Nhân viên (staff): Toàn quyền quản lý vận hành (đơn hàng, kho, sản phẩm, voucher, banner)
-- ==============================================================================

-- 1. Quản lý danh mục (Staff & Admin)
drop policy if exists "admin write categories" on public.categories;
create policy "admin write categories" on public.categories
  for all to authenticated using (public.is_staff_or_admin()) with check (public.is_staff_or_admin());

-- 2. Quản lý sản phẩm & biến thể & hình ảnh (Staff & Admin)
drop policy if exists "admin write products" on public.products;
create policy "admin write products" on public.products
  for all to authenticated using (public.is_staff_or_admin()) with check (public.is_staff_or_admin());

drop policy if exists "admin write product_variants" on public.product_variants;
create policy "admin write product_variants" on public.product_variants
  for all to authenticated using (public.is_staff_or_admin()) with check (public.is_staff_or_admin());

drop policy if exists "admin write product_images" on public.product_images;
create policy "admin write product_images" on public.product_images
  for all to authenticated using (public.is_staff_or_admin()) with check (public.is_staff_or_admin());

-- 3. Quản lý hồ sơ người dùng (CHỈ DÀNH CHO QUẢN TRỊ VIÊN ADMIN TOÀN QUYỀN)
drop policy if exists "admin read profiles" on public.profiles;
create policy "admin read profiles" on public.profiles
  for select to authenticated using (public.is_admin());

drop policy if exists "admin write profiles" on public.profiles;
create policy "admin write profiles" on public.profiles
  for all to authenticated using (public.is_admin()) with check (public.is_admin());

-- 4. Quản lý đơn hàng & chi tiết đơn & thanh toán (Staff & Admin)
drop policy if exists "admin read orders" on public.orders;
create policy "admin read orders" on public.orders
  for select to authenticated using (public.is_staff_or_admin());

drop policy if exists "admin write orders" on public.orders;
create policy "admin write orders" on public.orders
  for all to authenticated using (public.is_staff_or_admin()) with check (public.is_staff_or_admin());

drop policy if exists "admin read order_items" on public.order_items;
create policy "admin read order_items" on public.order_items
  for select to authenticated using (public.is_staff_or_admin());

drop policy if exists "admin read payments" on public.payments;
create policy "admin read payments" on public.payments
  for select to authenticated using (public.is_staff_or_admin());

-- 5. Quản lý banner & voucher & shop (Staff & Admin)
drop policy if exists "admin manage banners" on public.banners;
create policy "admin manage banners" on public.banners
  for all to authenticated using (public.is_staff_or_admin()) with check (public.is_staff_or_admin());

drop policy if exists "admin manage vouchers" on public.vouchers;
create policy "admin manage vouchers" on public.vouchers
  for all to authenticated using (public.is_staff_or_admin()) with check (public.is_staff_or_admin());

drop policy if exists "admin manage shops" on public.shops;
create policy "admin manage shops" on public.shops
  for all to authenticated using (public.is_staff_or_admin()) with check (public.is_staff_or_admin());


-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- MODULE: 07_permissions/01_schema_permissions.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- ==============================================================================
-- 01. SCHEMA & ROLE PERMISSIONS
-- Cấp quyền truy cập schema public, tables, sequences, routines cho các vai trò Supabase
-- Khắc phục triệt để lỗi PostgreSQL 42501 (Permission Denied for schema/table)
-- ==============================================================================

grant usage on schema public to postgres, anon, authenticated, service_role;
grant all on all tables in schema public to postgres, anon, authenticated, service_role;
grant all on all sequences in schema public to postgres, anon, authenticated, service_role;
grant all on all routines in schema public to postgres, anon, authenticated, service_role;

alter default privileges in schema public grant all on tables to postgres, anon, authenticated, service_role;
alter default privileges in schema public grant all on sequences to postgres, anon, authenticated, service_role;
alter default privileges in schema public grant all on routines to postgres, anon, authenticated, service_role;


-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- MODULE: 07_permissions/02_rpc_permissions.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- ==============================================================================
-- 02. RPC FUNCTION PERMISSIONS
-- Phân quyền thực thi các hàm Stored Procedure / RPC theo nguyên tắc bảo mật tối thiểu
-- ==============================================================================

-- 1. Hàm hệ thống và thanh toán: chỉ service_role (Backend API) được thực thi
revoke all on function public.create_order(uuid, jsonb, jsonb, text, int, text) from public, anon, authenticated;
grant execute on function public.create_order(uuid, jsonb, jsonb, text, int, text) to service_role;

revoke all on function public.settle_payment(text, boolean, text, text, text, jsonb) from public, anon, authenticated;
grant execute on function public.settle_payment(text, boolean, text, text, text, jsonb) to service_role;

revoke all on function public.expire_pending_orders() from public, anon, authenticated;
grant execute on function public.expire_pending_orders() to service_role;

revoke all on function public.adjust_stock(uuid, int, inventory_movement_reason, text, uuid) from public, anon, authenticated;
grant execute on function public.adjust_stock(uuid, int, inventory_movement_reason, text, uuid) to service_role;

revoke all on function public.admin_update_order_status(uuid, order_status, text, uuid) from public, anon, authenticated;
grant execute on function public.admin_update_order_status(uuid, order_status, text, uuid) to service_role;

-- 2. Hàm tra cứu đơn hàng: người dùng ẩn danh (anon) và đã đăng nhập đều có thể gọi
grant execute on function public.track_order_by_code_phone(text, text) to anon, authenticated, service_role;

-- 3. Hàm hủy đơn hàng của người mua: chỉ tài khoản đã đăng nhập (authenticated) được gọi
grant execute on function public.cancel_order_by_buyer(uuid, uuid) to authenticated, service_role;


